<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\{BelongsTo,HasMany};
class SponsorshipLead extends Model{use HasFactory;public const STAGES=['new','contacted','qualified','proposal','negotiation','won','lost'];protected $fillable=['uuid','advertiser_id','assigned_to','company_name','contact_name','contact_email','contact_phone','source','stage','estimated_value_cents','probability','target_close_date','next_follow_up_at','notes','lost_reason','won_at','lost_at'];protected $casts=['target_close_date'=>'date','next_follow_up_at'=>'date','won_at'=>'datetime','lost_at'=>'datetime'];public function advertiser():BelongsTo{return $this->belongsTo(Advertiser::class);}public function owner():BelongsTo{return $this->belongsTo(User::class,'assigned_to');}public function activities():HasMany{return $this->hasMany(SalesActivity::class);}public function proposals():HasMany{return $this->hasMany(SponsorshipProposal::class);}}
